//! Card copied by `tesso add card`.
//!
//! `title` and `description` are static strings (`title="Shift"`). An empty
//! string hides that line. The body is the default `<Children>` slot. A
//! `<template slot="footer">` fills `<Children name="footer">`. Named slots
//! need Fusor 0.1.6 or newer.

use fusor::prelude::*;

#[derive(FromInputs)]
pub struct Card {
    #[input]
    title: &'static str,
    #[input]
    description: &'static str,
}

fusor::template!("web/components/card.html");

css.content:
@layer components {
  .tesso-card {
    background: var(--card);
    color: var(--card-foreground);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    box-shadow: 0 0.25rem 0.75rem oklch(0% 0 0 / 0.12);
    padding: 1.5rem;
  }

  .tesso-card-header {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
    margin-bottom: 1rem;
  }

  .tesso-card-title {
    margin: 0;
    color: var(--card-foreground);
    font-size: 1.25rem;
    font-weight: 600;
    line-height: 1.25;
  }

  .tesso-card-description {
    margin: 0;
    color: var(--muted-foreground);
    font-size: 0.875rem;
    line-height: 1.5;
  }

  .tesso-card-body {
    display: flex;
    flex-direction: column;
    gap: 1rem;
  }

  .tesso-card-footer {
    display: flex;
    flex-wrap: wrap;
    gap: 0.5rem;
    margin-top: 1rem;
  }

  .tesso-card-title[hidden],
  .tesso-card-description[hidden],
  .tesso-card-footer:empty {
    display: none;
  }
}
